from quilldown_spec import PresentationStats


def test_load_json_presentationstats():
    json_data = r"""
    {
      "slides": 1,
      "textBoxes": 1,
      "bulletItems": 1,
      "images": 1,
      "links": 1,
      "speakerNotes": 1,
      "warnings": []
    }
    """
    data = json.loads(json_data, strict=False)
    instance = PresentationStats.load(data)
    assert instance is not None
    assert instance.slides == 1
    assert instance.text_boxes == 1
    assert instance.bullet_items == 1
    assert instance.images == 1
    assert instance.links == 1
    assert instance.speaker_notes == 1


