def test_roundtrip_json_presentationstats():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "slides": 1,
      "textBoxes": 1,
      "bulletItems": 1,
      "images": 1,
      "links": 1,
      "speakerNotes": 1,
      "warnings": []
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = PresentationStats.load(original_data)
    saved_data = instance.save()
    reloaded = PresentationStats.load(saved_data)
    assert reloaded is not None
    assert reloaded.slides == 1
    assert reloaded.text_boxes == 1
    assert reloaded.bullet_items == 1
    assert reloaded.images == 1
    assert reloaded.links == 1
    assert reloaded.speaker_notes == 1


